// Dynamic falling crate
const crate = realm3d.createCube(1, crateMat, {
  position: [0, 8, 0],
  scale: [1, 1, 1]
}).entityId;

realm3d.addCollider(crate, { type: 'box', halfExtents: [0.5, 0.5, 0.5] });
physics.addRigidBody(crate, {
