  width: 200,
  height: 80,
  backgroundColor: [0.1, 0.12, 0.18, 0.85], // Semi-transparent dark
  borderColor: [0.3, 0.4, 0.6, 1.0],
  borderWidth: 2,
  borderRadius: 6
